            </div>
          </v-alert>
          <!-- Step 3: Leave Request Form -->
          <v-form ref="form" v-model="valid" v-if="canShowForm">
            <ihris-questionnaire-section
              id="269f87392e1886642ecd316c58aebb8d"
              path="Basic"
              label="Leave Details"
              displayCondition=""
            >
              <v-row>
                <!-- Part Time: Batch Request -->
                <template v-if="selectedTrainingType === 'parttime'">
                  <v-col cols="12">
                    <v-alert type="info" dense outlined>
