          <!-- Actions -->
          <v-card-actions class="px-0 pt-4" v-if="canShowForm">
            <v-btn outlined color="grey" @click="$emit('cancel')">
              <v-icon left>mdi-close</v-icon>
              Cancel
            </v-btn>
            <v-spacer></v-spacer>
            <v-btn
              color="green"
              dark
              :disabled="!valid || submitting"
              :loading="submitting"
              @click="confirmSubmit"
            >
