</template>

<script>
import StaffSelectionDialog from "./staff-selection-dialog.vue";
import processQuestionnaire from "../../mixins/processQuestionnaire";
import { eventBus } from "@/main";
export default {
  name: "StudyLeaveRequest",
  mixins: [processQuestionnaire],
  props: {
    leaveType: {
      type: Object,
      required: true,
    },
    leaveInfo: {
      type: Object,
      required: true,
    },
    practitioner: {
      type: String,
      required: true,
    },
    requestId: {
      type: String,
      default: null,
    },
    loggedInStaff: {
      type: Object,
    },
  },

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/leave-request",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/leave-request-profile",
      studyleaveid: null,
      confirmDialog: false,
      overlay: false,
      valid: false,
      submitting: false,
      editMode: false,

      startDateMenu: false,
      endDateMenu: false,
      startDateReadOnly: false,
      endDateReadOnly: false,

      selectedTraining: null,
      selectedTrainingPlan: null,
      selectedRecommendation: null,
      skipTrainingPlan: false,
      showRecommendations: true,
      loadingDoctorStatus: false,

      loadingTrainingPlans: false,
      loadingRecommendations: false,

      trainingPlans: [],
      approvedRecommendations: [],
      incrementNeed: 0,

      calculatedDays: 0,
      calculatedMonths: 0,
      actingSupervisorDialogOpen: false,
      actingSupervisor: null,
      supportingDocLabel: "",

      formData: {
        actingSupervisor: {},
        comments: "",
        startDate: "",
        endDate: "",
        supportingDoc: {},
        institution: "",
        courseRef: null,
        courseOther: "",
        courseLevel: null,
        country: null,
        trainingLocation: "",
      },

      rules: {
        required: (value) => !!value || "This field is required",
        minLength: (min) => (value) =>
          !value || value.length >= min || `Minimum ${min} characters required`,
        phone: (value) =>
          !value || /^[0-9+\-\s()]+$/.test(value) || "Invalid phone number",
        endAfterStart: (value) => {
          if (!value || !this.formData.startDate) return true;
          return (
            new Date(value) >= new Date(this.formData.startDate) ||
            "End date must be after start date"
          );
        },
        maxDuration: (value) => {
          if (!value || !this.formData.startDate) return true;
          const months = this.calculateMonthsDifference(
            this.formData.startDate,
            value,
          );
          if (this.selectedTrainingType == "shortterm" && months > 6) {
            return `Duration cannot exceed 6 months for Long term training`;
          } else if (this.selectedTrainingType == "longterm" && months <= 6) {
            return `Duration cannot be below 6 months for ${this.selectedTrainingType} training`;
          } else if (this.selectedTrainingType === "parttime" && months > 999) {
            return `Part-time training duration seems too long`;
          }
          let days =
            this.$moment(this.formData.endDate).diff(
              this.formData.startDate,
              "days",
            ) + 1;
          // Self-arranged part-time doctors: enforce 56-day (8-week) ceiling
          if (
            this.isSelfArranged &&
            this.selectedTrainingType === "parttime" &&
            days > 56
          ) {
            return "Duration cannot exceed 56 days (8 weeks) for part-time training";
          }
          // Skip balance check for self-arranged (no pre-approved training)
          if (
            !this.isSelfArranged &&
            this.selectedTrainingDetails?.balance !== null &&
            days > parseInt(this.selectedTrainingDetails.balance)
          ) {
            return (
              "Exceeds the balance of " + this.selectedTrainingDetails.balance
            );
          }
          return true;
        },
      },
    };
  },

  computed: {
    excludedStaffIds() {
      return [this.practitioner];
    },
    minStartDate() {
      const today = new Date();
      return today.toISOString().substr(0, 10);
    },

    includesWeekendsHint() {
      return "Includes weekends and public holidays";
    },

    hasAnyTraining() {
      const hasLongterm =
        this.leaveType.details.longterm &&
        this.leaveType.details.longterm.length > 0;
      const hasShortterm =
        this.leaveType.details.shortterm &&
        this.leaveType.details.shortterm.length > 0;
      const hasParttime =
        this.leaveType.details.parttime &&
        this.leaveType.details.parttime.length > 0;
      return hasLongterm || hasShortterm || hasParttime;
    },

    hasAvailableTraining() {
      return (
        this.availableLongtermTrainings.length > 0 ||
        this.availableShorttermTrainings.length > 0 ||
        this.availableParttimeTrainings.length > 0 ||
        this.isDoctor
      );
    },

    hasLongtermTaken() {
      if (!this.leaveType.details.longterm) return false;
      return this.leaveType.details.longterm.some((t) => t.taken === true);
    },

    hasShorttermTaken() {
      if (!this.leaveType.details.shortterm) return false;
      return this.leaveType.details.shortterm.some((t) => t.taken === true);
    },

    availableLongtermTrainings() {
      if (!this.leaveType.details.longterm) return [];
      if (this.hasLongtermTaken || this.hasShorttermTaken) return [];
      return this.leaveType.details.longterm.filter((t) => !t.taken);
    },

    availableShorttermTrainings() {
      if (!this.leaveType.details.shortterm) return [];
      if (this.hasLongtermTaken || this.hasShorttermTaken) return [];
      return this.leaveType.details.shortterm.filter((t) => !t.taken);
    },

    availableParttimeTrainings() {
      if (!this.leaveType.details.parttime) return [];
      return this.leaveType.details.parttime.filter((t) => !t.taken);
    },

    hasExistingParttimeAllocation() {
      return this.availableParttimeTrainings.some(
        (t) => t.category === "doctor-exception",
      );
    },

    selectedTrainingType() {
      if (!this.selectedTraining) return null;
      const parts = this.selectedTraining.split("-");
      // self-longterm / self-shortterm / self-parttime
      if (parts[0] === "self") return parts[1];
      return parts[0];
    },

    selectedTrainingId() {
      if (!this.selectedTraining) return null;
      const parts = this.selectedTraining.split("-");
      if (parts[0] === "self") return null; // no linked training record
      return parts[1];
    },

    isSelfArranged() {
      return (
        this.selectedTraining !== null &&
        this.selectedTraining.startsWith("self-")
      );
    },

    selectedTrainingDetails() {
      if (!this.selectedTrainingType) return null;
      // Self-arranged: return a stub so the form doesn't break
      if (this.isSelfArranged) {
        return {
          balance: null,
          maxDays: null,
          name: null,
          institution: null,
          id: null,
          category: null,
        };
      }
      if (!this.selectedTrainingId) return null;
      const trainingList = this.leaveType.details[this.selectedTrainingType];
      if (!trainingList) return null;
      return trainingList.find((t) => t.id === this.selectedTrainingId) || null;
    },

    canShowForm() {
      return this.selectedTraining !== null;
    },

    isDoctor() {
      return this.loggedInStaff.isDoctor;
    },

    hasExistingStudyLeave() {
      return (
        this.selectedTrainingType === "parttime" &&
        !this.isSelfArranged &&
        !!(
          this.selectedTrainingDetails?.academicDetails?.qualification ||
          this.selectedTrainingDetails?.academicDetails?.qualificationOther
        )
      );
    },

    qualificationDisplayName() {
      if (this.formData.courseOther) return this.formData.courseOther;
      const ref = this.formData.courseRef;
      if (!ref) return "";
      if (ref.display) return ref.display;
      if (ref.reference) return ref.reference;
      return "";
    },

    isOtherQualification() {
      return (
        this.formData.courseRef?.reference === "Basic/otherqualificationname"
      );
    },
  },

  created() {
    eventBus.$on("Basic.courselevel", (value) => {
      if (!value) {
        this.formData.courseLevel = null;
      } else if (typeof value === "string") {
        const [system, code] = value.split("#");
        this.formData.courseLevel = { system, code };
      } else {
        this.formData.courseLevel = value;
      }
    });
    eventBus.$on("Basic.course", (value) => {
      this.formData.courseRef =
        typeof value === "string" ? { reference: value } : value || null;
    });
    eventBus.$on("Basic.courseother", (value) => {
      this.formData.courseOther = value || "";
    });
    eventBus.$on("Basic.country", (value) => {
      if (!value) {
        this.formData.country = null;
      } else if (typeof value === "string") {
        const [system, code] = value.split("#");
        this.formData.country = { system, code };
      } else {
        this.formData.country = value;
      }
    });
    eventBus.$on("Basic.location", (value) => {
      this.formData.trainingLocation = value || "";
    });
  },

  watch: {
    requestId: {
      immediate: true,
      async handler(id) {
        if (id) {
          await this.loadEditingData(id);
        }
      },
    },
    selectedTrainingDetails: {
      immediate: true,
      handler(training) {
        if (!training || training.id === null) return;
        if (this.editMode) return;
        const ad = training.academicDetails || {};
        if (
          this.selectedTrainingType === "parttime" &&
          (ad.qualification || ad.qualificationOther)
        ) {
          this.formData.courseRef = ad.qualification || null;
          this.formData.courseOther = ad.qualificationOther || "";
          this.formData.courseLevel = ad.level || null;
          this.formData.country = ad.country || null;
          this.formData.trainingLocation = ad.location || "";
          this.formData.institution = ad.institution || training.institution;
          this.studyleaveid = ad.id || null;
          this.incrementNeed++;
        } else {
          // No existing study leave for this training - prefill from the
          // recommendation/plan but allow the user to change it
          this.formData.courseRef = training.qualification || null;
          this.formData.courseOther = training.qualificationOther || "";
          this.formData.courseLevel = training.level || null;
          this.formData.country = training.country || null;
          this.formData.trainingLocation = training.location || "";
          this.formData.institution = training.institution;
          this.studyleaveid = null;
          this.incrementNeed++;
        }
      },
    },
  },

  methods: {
    // NEW METHODS FOR TRAINING SELECTION
    onTrainingSelect(skipFieldReset = false) {
      // Always set the supporting doc label based on training type
      if (this.selectedTrainingType === "longterm") {
        this.supportingDocLabel = "Admission Letter";
      } else if (this.selectedTrainingType === "shortterm") {
        this.supportingDocLabel = "Supporting Document";
      } else {
        this.supportingDocLabel = "Exam Proof i.e Timetable";
      }

      if (this.isSelfArranged) {
        this.studyleaveid = null;
        this.formData.trainingId = null;
        this.formData.trainingCategory = null;
        this.formData.trainingType = this.selectedTrainingType;
        if (!skipFieldReset) {
          this.formData.courseRef = null;
          this.formData.courseOther = "";
          this.formData.courseLevel = null;
          this.formData.country = null;
          this.formData.trainingLocation = "";
          this.formData.institution = "";
        }
      } else if (this.selectedTrainingDetails) {
        this.formData.trainingId = this.selectedTrainingDetails.id;
        this.formData.trainingCategory = this.selectedTrainingDetails.category;
        this.formData.trainingType = this.selectedTrainingType;
      }

      this.$nextTick(() => {
        if (this.$refs.form) {
          this.$refs.form.validate();
        }
      });
    },

    formatDate(dateString) {
      if (!dateString) return "";
      // Handle DD-MM-YYYY format
      const parts = dateString.split("-");
      if (parts.length === 3) {
        const day = parts[0];
        const monthNames = [
          "Jan",
          "Feb",
          "Mar",
          "Apr",
          "May",
          "Jun",
          "Jul",
          "Aug",
          "Sep",
          "Oct",
          "Nov",
          "Dec",
        ];
        const monthNum = parseInt(parts[1]) - 1;
        const month = monthNames[monthNum] || parts[1];
        const year = parts[2];
        return `${day}-${month}-${year}`;
      }
      // Fallback for other formats
      const date = new Date(dateString);
      return date.toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },

    getProgressColor(balance, maxDays) {
      if (maxDays === 0) return "grey";
      const percentage = (balance / maxDays) * 100;
      if (percentage > 50) return "green";
      if (percentage > 25) return "orange";
      return "red";
    },

    // EXISTING METHODS
    actingSupervisorSelected(staff) {
      this.formData.actingSupervisor = staff;
    },
    clearReliefOfficer() {
      this.formData.actingSupervisor = {};
    },

    calculateLeaveDays() {
      if (!this.formData.startDate || !this.formData.endDate) {
        this.calculatedDays = 0;
        this.calculatedMonths = 0;
        return;
      }

      const start = new Date(this.formData.startDate);
      const end = new Date(this.formData.endDate);

      // Calculate total days (including weekends and holidays for study leave)
      const diffTime = Math.abs(end - start);
      this.calculatedDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;

      this.calculatedMonths = this.calculateMonthsDifference(
        this.formData.startDate,
        this.formData.endDate,
      );
    },

    calculateMonthsDifference(startDate, endDate) {
      const start = this.$moment(startDate);
      const end = this.$moment(endDate);

      // Calculate difference in days
      const diffDays = end.diff(start, "days");

      // Convert to months (approximating 30.44 days per month)
      const months = diffDays / 30.44;

      // Round to 1 decimal place and ensure minimum of 0.1
      return Math.max(Math.round(months * 10) / 10, 0.1);
    },

    getStatusColor(status) {
      const colors = {
        draft: "grey",
        pending: "orange",
        approved: "green",
        rejected: "red",
      };
      return colors[status] || "grey";
    },

    resetForm() {
      this.formData = {
        actingSupervisor: {},
        comments: "",
        startDate: "",
        endDate: "",
        supportingDoc: {},
        institution: "",
        courseRef: null,
        courseOther: "",
        courseLevel: null,
        country: null,
        trainingLocation: "",
      };
      this.calculatedDays = 0;
      this.calculatedMonths = 0;
      this.incrementNeed++;
    },

    getExtValue(resource, urlPart, valueType) {
      const ext = resource.extension?.find((ext) => ext.url.includes(urlPart));
      return ext ? ext[valueType] : null;
    },

    async loadEditingData(id) {
      this.editMode = true;
      this.fhirId = id;

      try {
        let url = `/fhir/Basic?_id=${id}&_revinclude=Basic:leaverequest`;
        let response = await fetch(url);
        let resources = await response.json();
        let leaverequest = resources.entry.find((entry) => {
          return entry.resource.id == id;
        })?.resource;
        let studyleave = resources.entry.find((entry) => {
          return entry.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/study-leave-profile",
          );
        })?.resource;
        // Extract form data
        this.formData.startDate = this.getExtValue(
          leaverequest,
          "start-date",
          "valueDate",
        );
        this.formData.endDate = this.getExtValue(
          leaverequest,
          "end-date",
          "valueDate",
        );
        this.formData.institution = this.getExtValue(
          studyleave,
          "planning-institution",
          "valueString",
        );
        const qualNameExt = studyleave.extension?.find(
          (ext) =>
            ext.url.includes("qualification-name") &&
            !ext.url.includes("other"),
        );
        if (qualNameExt?.valueReference) {
          this.formData.courseRef = qualNameExt.valueReference;
        }
        this.formData.courseOther =
          this.getExtValue(
            studyleave,
            "qualification-name-other",
            "valueString",
          ) || "";
        const levelExt = studyleave.extension?.find((ext) =>
          ext.url.includes("qualification-level"),
        );
        if (levelExt?.valueCoding) {
          this.formData.courseLevel = levelExt.valueCoding;
        }
        const countryExt = studyleave.extension?.find((ext) =>
          ext.url.endsWith("/country"),
        );
        if (countryExt?.valueCoding) {
          this.formData.country = countryExt.valueCoding;
        }
        this.formData.trainingLocation =
          this.getExtValue(studyleave, "training-location", "valueString") ||
          "";
        this.formData.comments = this.getExtValue(
          leaverequest,
          "comments",
          "valueString",
        );

        // Extract acting supervisor
        const actingSupExt = leaverequest.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/acting-supervisor",
        );
        if (actingSupExt?.valueReference?.reference) {
          const actingId = actingSupExt.valueReference.reference.split("/")[1];
          try {
            const actingResponse = await fetch(
              `/fhir/Practitioner/${actingId}`,
            );
            const actingPractitioner = await actingResponse.json();
            const name = actingPractitioner.name?.[0];
            this.formData.actingSupervisor = {
              id: actingId,
              name: name
                ? `${name.given?.join(" ")} ${name.family}`.trim()
                : "Unknown",
            };
          } catch (err) {
            console.error("Error loading acting supervisor:", err);
          }
        }

        // Extract supporting document
        const docExt = leaverequest.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/supporting-document",
        );
        if (docExt?.valueAttachment) {
          this.formData.supportingDoc = docExt.valueAttachment;
        }

        // Calculate days
        let type = studyleave.extension.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/training-type"
          );
        })?.valueCoding?.code;
        let cat = studyleave.extension.find((ext) => {
          return (
            ext.url ===
              "http://ihris.org/fhir/StructureDefinition/training-recommendation-reference" ||
            ext.url ===
              "http://ihris.org/fhir/StructureDefinition/training-plan-reference"
          );
        });
        if (!cat) {
          // No linked training plan/recommendation — either a self-arranged
          // (doctor exception) request, or a reuse of an existing
          // doctor-exception part-time study leave with remaining balance
          const existingException = this.leaveType.details[type]?.find(
            (det) =>
              det.id === studyleave.id && det.category === "doctor-exception",
          );
          if (existingException) {
            this.selectedTraining = type + "-" + existingException.id;
          } else {
            this.selectedTraining = "self-" + type;
          }
          this.calculateLeaveDays();
          this.onTrainingSelect(true);
          this.incrementNeed++;
          this.$nextTick(() => {
            this.studyleaveid = studyleave.id;
          });
          return;
        }
        let category = "plan";
        if (
          cat.url ===
          "http://ihris.org/fhir/StructureDefinition/training-recommendation-reference"
        ) {
          category = "recommendation";
        }
        let details = this.leaveType.details[type].find((det) => {
          return (
            det.id == cat.valueReference.reference.split("/")[1] &&
            det.category === category
          );
        });
        this.selectedTraining = type + "-" + details.id;
        this.calculateLeaveDays();
        this.onTrainingSelect();
        this.incrementNeed++;
        this.$nextTick(() => {
          this.studyleaveid = studyleave.id;
        });
      } catch (error) {
        console.error("Error loading editing data:", error);
        this.showSnackbar("Error loading leave request data", "error");
      }
    },

    confirmSubmit() {
      this.$refs.form.validate();
      if (!this.valid) {
        this.showSnackbar("Please complete all required fields", "warning");
        return;
      }
      this.confirmDialog = true;
    },

    async submitRequest() {
      if (!this.$refs.form.validate()) {
        return;
      }
      this.confirmDialog = false;
      this.submitting = true;
      this.overlay = true;

      try {
        this.fhir = {
          leaveCategory: "study-leave",
          studyleaveid: this.studyleaveid,
          requestDate: new Date().toISOString().split("T")[0],
          startDate: this.formData.startDate,
          endDate: this.formData.endDate,
          comments: this.formData.comments,
          actingSupervisor: this.formData.actingSupervisor?.id,
          institution: this.formData.institution,
          course: this.formData.courseRef,
          courseOther: this.formData.courseOther || undefined,
          courseLevel: this.formData.courseLevel?.code || undefined,
          country:
            typeof this.formData.country === "object"
              ? this.formData.country?.code
              : this.formData.country || undefined,
          trainingLocation: this.formData.trainingLocation || undefined,
          trainingType: this.selectedTrainingType,
          trainingCategory: this.formData.trainingCategory,
          trainingId: this.formData.trainingId,
        };
        //processFHIR will handle the fhir-attachment
        await this.processFHIR();
        this.showSnackbar(
          this.editMode
            ? "Study leave request updated successfully!"
            : "Study leave request submitted successfully!",
          "success",
        );

        // Reset form
        this.resetForm();
        this.selectedTraining = null;
        this.overlay = false;
        this.submitting = false;
        this.editMode = false;
        this.fhirId = "";
        this.studyleaveid = null;
        this.$emit("submit");
      } catch (error) {
        console.error("Error submitting study leave request:", error);
        this.showSnackbar(
          error.message || "Error submitting study leave request",
          "error",
        );
        this.overlay = false;
        this.submitting = false;
      } finally {
        this.submitting = false;
      }
    },

    showSnackbar(message, color) {
      this.$emit("snackbar", { message, color });
    },

    getUtilizationColorClass(balance, maxDays) {
      const percentage = (balance / maxDays) * 100;
      if (percentage > 50) return "green--text text--darken-2";
      if (percentage > 25) return "orange--text text--darken-2";
      return "red--text text--darken-2";
    },
  },
  components: {
    StaffSelectionDialog,
    "fhir-attachment": () => import("@/components/fhir/fhir-attachment"),
    "fhir-choice": () => import("@/components/fhir/fhir-choice"),
    "fhir-reference": () => import("@/components/fhir/fhir-reference"),
    "fhir-string": () => import("@/components/fhir/fhir-string"),
    "ihris-questionnaire-section": () =>
      import("@/components/ihris/ihris-questionnaire-section"),
  },
};
</script>

