<template>
  <v-dialog v-model="dialog" max-width="900px" persistent scrollable>
    <v-card>
      <v-card-title class="primary white--text py-3">
        <v-icon left color="white">mdi-account-search</v-icon>
        {{ title }}
        <v-spacer></v-spacer>
        <v-btn icon dark @click="close">
          <v-icon>mdi-close</v-icon>
        </v-btn>
      </v-card-title>

      <v-card-text class="pa-0">
        <!-- Search Bar -->
        <v-container fluid class="pa-4">
          <v-row dense>
            <v-col cols="12">
              <v-text-field
                v-model="searchQuery"
                placeholder="Search by name..."
                prepend-inner-icon="mdi-magnify"
                outlined
                dense
                clearable
                hide-details
                @input="debouncedSearch"
                @click:clear="clearSearch"
              >
                <template v-slot:append>
                  <v-btn
                    color="primary"
                    @click="loadPractitioners(true)"
                    :loading="loadingPractitioners"
                    small
                  >
                    <v-icon left small>mdi-magnify</v-icon>
                    Search
                  </v-btn>
                </template>
              </v-text-field>
            </v-col>
          </v-row>
        </v-container>

        <v-divider></v-divider>

        <!-- Loading State -->
        <div v-if="loadingPractitioners" class="text-center py-12">
          <v-progress-circular
            indeterminate
            color="primary"
            size="64"
          ></v-progress-circular>
          <p class="mt-4 subtitle-1 grey--text">Loading staff members...</p>
        </div>

        <!-- No Results -->
        <div v-else-if="practitioners.length === 0" class="text-center py-12">
          <v-icon size="80" color="grey lighten-2">mdi-account-off</v-icon>
          <h3 class="title mt-4 mb-2 grey--text">No Staff Members Found</h3>
          <p class="body-1 grey--text" v-if="searchQuery">
            Try adjusting your search criteria
          </p>
        </div>

        <!-- Staff List -->
        <v-list v-else two-line class="pa-0">
          <template v-for="(practitioner, index) in practitioners">
            <v-list-item
              :key="practitioner.id"
              @click="selectPractitioner(practitioner)"
              class="staff-list-item"
              :class="{ 'selected-item': selectedId === practitioner.id }"
            >
              <v-list-item-avatar color="primary">
                <v-icon dark>mdi-account</v-icon>
              </v-list-item-avatar>

              <v-list-item-content>
                <v-list-item-title class="font-weight-medium">
                  {{ practitioner.name }}
                </v-list-item-title>
                <v-list-item-subtitle>
                  <v-icon small class="mr-1">mdi-briefcase</v-icon>
                  {{ practitioner.position || "Position not specified" }}
                </v-list-item-subtitle>
              </v-list-item-content>

              <v-list-item-action>
                <v-btn
                  icon
                  color="primary"
                  @click.stop="selectPractitioner(practitioner)"
                >
                  <v-icon>{{
                    selectedId === practitioner.id
                      ? "mdi-check-circle"
                      : "mdi-checkbox-blank-circle-outline"
                  }}</v-icon>
                </v-btn>
              </v-list-item-action>
            </v-list-item>

            <v-divider
              :key="`divider-${practitioner.id}`"
              v-if="index < practitioners.length - 1"
            ></v-divider>
          </template>
        </v-list>

        <!-- Pagination -->
        <v-container
          fluid
          class="pa-4 border-top"
          v-if="totalPractitioners > itemsPerPage && !loadingPractitioners"
        >
          <v-row align="center" dense>
            <v-col cols="12" sm="6">
              <div class="caption grey--text">
                Showing {{ startIndex + 1 }}-{{ endIndex }} of
                {{ totalPractitioners }} staff members
              </div>
            </v-col>
            <v-col cols="12" sm="6" class="text-sm-right">
              <v-btn
                text
                small
                :disabled="currentPage === 1 || loadingPractitioners"
                @click="previousPage"
                class="mr-2"
              >
                <v-icon left small>mdi-chevron-left</v-icon>
                Previous
              </v-btn>
              <span class="caption grey--text mx-2">
                Page {{ currentPage }} of {{ totalPages }}
              </span>
              <v-btn
                text
                small
                :disabled="currentPage === totalPages || loadingPractitioners"
                @click="nextPage"
              >
                Next
                <v-icon right small>mdi-chevron-right</v-icon>
              </v-btn>
            </v-col>
          </v-row>
        </v-container>
      </v-card-text>

      <v-divider></v-divider>

      <v-card-actions class="pa-4">
        <v-btn outlined color="grey" @click="close">
          <v-icon left small>mdi-close</v-icon>
          Cancel
        </v-btn>
        <v-spacer></v-spacer>
        <v-btn color="primary" :disabled="!selectedId" @click="confirm">
          <v-icon left small>mdi-check</v-icon>
          Select Staff Member
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
export default {
  name: "StaffSelectionDialog",

  props: {
    value: {
      type: Boolean,
      default: false,
    },
    title: {
      type: String,
      default: "Select Staff Member",
    },
    excludeIds: {
      type: Array,
      default: () => [],
    },
  },

  data() {
    return {
      searchQuery: "",
      loadingPractitioners: false,
      practitioners: [],
      selectedId: null,
      selectedPractitioner: null,

      // Pagination
      currentPage: 1,
      prevPage: 1,
      itemsPerPage: 10,
      totalPractitioners: 0,
      link: [],
    };
  },

  computed: {
    dialog: {
      get() {
        return this.value;
      },
      set(value) {
        this.$emit("input", value);
      },
    },

    totalPages() {
      return Math.ceil(this.totalPractitioners / this.itemsPerPage) || 1;
    },

    startIndex() {
      return (this.currentPage - 1) * this.itemsPerPage;
    },

    endIndex() {
      const end = this.currentPage * this.itemsPerPage;
      return Math.min(end, this.totalPractitioners);
    },
  },

  watch: {
    value(newVal) {
      if (newVal) {
        this.resetDialog();
        this.loadPractitioners(true);
      }
    },
  },

  created() {
    // Create debounced search function
    this.debouncedSearch = this.debounce(() => {
      this.loadPractitioners(true);
    }, 500);
  },

  methods: {
    async loadPractitioners(restart = false) {
      this.loadingPractitioners = true;

      try {
        let url = "";

        if (restart) {
          this.currentPage = 1;
        }

        // Build URL based on pagination
        if (this.currentPage > 1 && this.link.length > 0) {
          if (this.currentPage === this.prevPage - 1) {
            url =
              this.link.find((link) => link.relation === "previous")?.url || "";
          } else if (this.currentPage === this.prevPage + 1) {
            url = this.link.find((link) => link.relation === "next")?.url || "";
          }

          if (url) {
            url = url
              .replace(/_getpages=[^&]*&*/, "")
              .replace("/fhir?", "/fhir/PractitionerRole?");
            url = url.substring(url.indexOf("/fhir/"));

            if (url.indexOf("_include=PractitionerRole:practitioner") === -1) {
              url = url + "&_include=PractitionerRole:practitioner";
            }
            if (url.indexOf("_include=PractitionerRole:roleposition") === -1) {
              url = url + "&_include=PractitionerRole:roleposition";
            }
            if (url.indexOf("_sort=-_lastUpdated") === -1) {
              url = url + "&_sort=-_lastUpdated";
            }
            if (url.indexOf("_total=accurate") === -1) {
              url = url + "&_total=accurate";
            }
          }
        }

        // Build initial URL
        if (url === "") {
          url = `/fhir/PractitionerRole?_count=${this.itemsPerPage}&_include=PractitionerRole:practitioner&_include=PractitionerRole:roleposition&_sort=-_lastUpdated&_total=accurate`;

          // Add search term if exists
          if (this.searchQuery) {
            url += `&practitioner.name:contains=${encodeURIComponent(
              this.searchQuery,
            )}`;
          }
        }

        this.prevPage = this.currentPage;

        const response = await fetch(url);
        const bundle = await response.json();

        if (bundle.total >= 0) {
          this.totalPractitioners = bundle.total;
          this.link = bundle.link || [];
        }

        if (bundle.entry) {
          const practitionerMap = new Map();
          const positionMap = new Map();

          // Process practitioners
          bundle.entry.forEach((entry) => {
            if (entry.resource.resourceType === "Practitioner") {
              const practitioner = entry.resource;
              const name = practitioner.name?.[0];
              const fullName = name
                ? `${name.given?.join(" ") || ""} ${name.family || ""}`.trim()
                : "Unknown";

              practitionerMap.set(practitioner.id, {
                id: practitioner.id,
                name: fullName,
                position: "",
              });
            }
          });

          // Process position resources (Basic resources)
          bundle.entry.forEach((entry) => {
            if (entry.resource.resourceType === "Basic") {
              positionMap.set(entry.resource.id, entry.resource);
            }
          });

          // Process PractitionerRole to link positions
          bundle.entry.forEach((entry) => {
            if (entry.resource.resourceType === "PractitionerRole") {
              const role = entry.resource;
              const practitionerId = role.practitioner?.reference?.split(
                "/",
              )[1];

              if (practitionerId && practitionerMap.has(practitionerId)) {
                const practitioner = practitionerMap.get(practitionerId);

                const positionRef = role.extension?.find(
                  (ext) =>
                    ext.url ===
                    "http://ihris.org/fhir/StructureDefinition/position-reference",
                )?.valueReference?.reference;

                if (positionRef) {
                  const positionId = positionRef.split("/")[1];
                  const positionResource = positionMap.get(positionId);

                  if (positionResource) {
                    practitioner.position = positionResource.extension?.find(
                      (ext) =>
                        ext.url ===
                        "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
                    )?.valueString;
                  }
                }
              }
            }
          });

          // Convert map to array and filter excluded IDs
          let filteredPractitioners = Array.from(practitionerMap.values());

          if (this.excludeIds && this.excludeIds.length > 0) {
            filteredPractitioners = filteredPractitioners.filter(
              (p) => !this.excludeIds.includes(p.id),
            );
          }

          this.practitioners = filteredPractitioners.sort((a, b) =>
            a.name.localeCompare(b.name),
          );
        } else {
          this.practitioners = [];
        }
      } catch (error) {
        console.error("Error loading practitioners:", error);
        this.practitioners = [];
      } finally {
        this.loadingPractitioners = false;
      }
    },

    selectPractitioner(practitioner) {
      if (this.selectedId === practitioner.id) {
        // Deselect if clicking same item
        this.selectedId = null;
        this.selectedPractitioner = null;
      } else {
        this.selectedId = practitioner.id;
        this.selectedPractitioner = practitioner;
      }
    },

    confirm() {
      if (this.selectedPractitioner) {
        this.$emit("selected", {
          id: this.selectedPractitioner.id,
          name: this.selectedPractitioner.name,
          position: this.selectedPractitioner.position,
        });
        this.close();
      }
    },

    close() {
      this.dialog = false;
      this.resetDialog();
    },

    resetDialog() {
      this.selectedId = null;
      this.selectedPractitioner = null;
      this.searchQuery = "";
      this.currentPage = 1;
      this.prevPage = 1;
      this.practitioners = [];
    },

    clearSearch() {
      this.searchQuery = "";
      this.loadPractitioners(true);
    },

    nextPage() {
      if (this.currentPage < this.totalPages) {
        this.currentPage++;
        this.loadPractitioners();
      }
    },

    previousPage() {
      if (this.currentPage > 1) {
        this.currentPage--;
        this.loadPractitioners();
      }
    },

    debounce(func, wait) {
      let timeout;
      return function executedFunction(...args) {
        const later = () => {
          clearTimeout(timeout);
          func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
      };
    },
  },
};
</script>

<style scoped>
.border-top {
  border-top: 1px solid #e0e0e0;
}

.staff-list-item {
  cursor: pointer;
  transition: background-color 0.2s;
}

.staff-list-item:hover {
  background-color: rgba(0, 0, 0, 0.04);
}

.selected-item {
  background-color: rgba(33, 150, 243, 0.08);
}

.selected-item:hover {
  background-color: rgba(33, 150, 243, 0.12);
}
</style>
